BEGIN TRANSACTION;
CREATE TABLE ai_model_lineage_log (
    log_id INTEGER PRIMARY KEY AUTOINCREMENT,
    project_id TEXT NOT NULL,
    stage TEXT NOT NULL,
    model TEXT NOT NULL,
    provider TEXT NOT NULL,
    prompt_tokens INTEGER,
    completion_tokens INTEGER,
    status_code INTEGER DEFAULT 200,
    recorded_at DATETIME DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE community_reviews (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    project_id TEXT,
    reviewer_name TEXT NOT NULL,
    reviewer_title TEXT NOT NULL,
    reviewer_organization TEXT NOT NULL,
    rating INTEGER DEFAULT 5,
    review_text TEXT NOT NULL,
    verified_badge TEXT DEFAULT 'VERIFIED_COMMUNITY_ENGINEER',
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY(project_id) REFERENCES community_verified_projects(project_id)
);
CREATE TABLE community_stats (
    stat_key TEXT PRIMARY KEY,
    stat_value TEXT NOT NULL,
    description TEXT
);
CREATE TABLE community_verified_projects (
    project_id TEXT PRIMARY KEY,
    app_name TEXT NOT NULL,
    tagline TEXT,
    preset TEXT,
    repo_url TEXT NOT NULL,
    commit_hash TEXT NOT NULL,
    generator_model TEXT DEFAULT 'anthropic/claude-3-7-sonnet',
    provider_name TEXT DEFAULT 'OmniRoute Swarm Engine',
    router_engine TEXT DEFAULT 'OmniRoute v3.8.52 (Node.js/PM2)',
    embedding_model TEXT DEFAULT 'voyage-ai/voyage-3-lite',
    lineage_hash TEXT,
    headmaster_score INTEGER DEFAULT 100,
    status TEXT DEFAULT 'COMMUNITY_VERIFIED',
    community_stamp_id TEXT NOT NULL,
    crypto_stamp_hash TEXT NOT NULL,
    native_resolution_android TEXT DEFAULT '1080x2400 Pixel 6 (API 34)',
    native_resolution_ios TEXT DEFAULT '1179x2556 iPhone 15 Pro (iOS 18)',
    clean_architecture INTEGER DEFAULT 1,
    zero_emojis INTEGER DEFAULT 1,
    community_rating REAL DEFAULT 4.98,
    community_reviews_count INTEGER DEFAULT 24,
    business_value_summary TEXT,
    verified_at DATETIME DEFAULT CURRENT_TIMESTAMP
);

